package org.example.post;

import java.time.LocalDateTime;

// MyBatis generated key를 받는 입력 객체
public class DraftInsertRow {
    private Long id;
    private final Long boardId;
    private final Long authorId;
    private final String title;
    private final String content;
    private final String visibility;
    private final LocalDateTime now;

    public DraftInsertRow(Long boardId, Long authorId, String title, String content,
                          String visibility, LocalDateTime now) {
        this.boardId = boardId;
        this.authorId = authorId;
        this.title = title;
        this.content = content;
        this.visibility = visibility;
        this.now = now;
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public Long getBoardId() { return boardId; }
    public Long getAuthorId() { return authorId; }
    public String getTitle() { return title; }
    public String getContent() { return content; }
    public String getVisibility() { return visibility; }
    public LocalDateTime getNow() { return now; }
}

